// Extended question bank, tagged by ISO 19650 part and level. Original, paraphrased questions written
// for learning — not the standards' text. UK National Annex codes are used where codes appear.
// Merged into QUESTIONS in learn.ts, so the server grader sees them. Ids are stable: append new rows
// at the end of a group, never reorder or delete.
//
// Options are written with the correct answer wherever is natural; the helper then rotates the options
// (keeping their cyclic order) so the correct answer lands in a position derived from the id. Rows with
// ordered options (e.g. Annex A–D) pass `keep` to stay as written.

import type { Question, TOPICS } from "./learn";

type Topic = (typeof TOPICS)[number];
type Lv = "B" | "I" | "A";
type Row = [Lv, string, string[], number, string, ("keep" | undefined)?];
const LEVEL = { B: "Beginner", I: "Intermediate", A: "Advanced" } as const;

const hash = (s: string) => [...s].reduce((h, c) => (h * 31 + c.charCodeAt(0)) >>> 0, 7);

const B = (prefix: string, topic: Topic, part: Question["part"], rows: Row[]): Question[] =>
  rows.map(([lv, q, opts, answer, why, keep], i) => {
    const id = `${prefix}-${i + 1}`;
    let options = opts, ans = answer;
    if (!keep && opts.length === 4) {
      const target = hash(id) % 4, s = (target - answer + 4) % 4;
      options = opts.map((_, k) => opts[(k - s + 4) % 4]);
      ans = target;
    }
    return { id, topic, ...(part ? { part } : {}), level: LEVEL[lv], q, options, answer: ans, why };
  });

